# renewal_aura.gd - A temporary aura for Annadaeus's Song of Renewal
extends Area2D

@export var heal_amount: int = 4
@export var heal_interval: float = 3.0
@export var buff_strength: float = 1.2 # 20% damage increase
@export var buff_duration: float = 10.0
@export var aura_duration: float = 8.0 # How long the aura exists
@export var target_groups: Array[String] = ["friendly", "player", "healer"]

@onready var despawn_timer: Timer = $despawn_timer

func _ready():
	# Timer to remove the aura after its total duration
	if despawn_timer:
		despawn_timer.wait_time = aura_duration
		despawn_timer.one_shot = true
		despawn_timer.timeout.connect(despawn)
		despawn_timer.start()

func _on_body_entered(body: Node) -> void:
	_apply_effect_to_body(body)

func _on_body_exited(body: Node) -> void:
	# Optional: logic to remove buff when body exits the area
	pass

func _apply_effect_to_body(body: Node):
	for group in target_groups:
		if body.is_in_group(group):
			# Apply healing effect
			if body.has_method("heal"):
				body.heal(heal_amount)

			# Apply buff effect (requires `apply_buff` method on target)
			if body.has_method("apply_buff"):
				body.apply_buff(buff_strength, buff_duration)
			break

func despawn():
	# Safely remove the aura from the scene
	if get_parent() is NodePool:
		get_parent().despawn(self)
	else:
		queue_free()

	if closest and is_instance_valid(closest) and global_position.distance_to(closest.global_position) < min_enemy_range:
		var away := global_position.direction_to(closest.global_position).normalized()
		velocity = velocity.lerp(-away * max_speed, acceleration * delta)
	else:
		velocity = velocity.lerp(Vector2.ZERO, drag)

func _escaping_state(delta: float) -> void:
	# Move away from closest enemy
	var closest_enemy = _find_closest_mob()
	if closest_enemy and is_instance_valid(closest_enemy):
		var direction = global_position.direction_to(closest_enemy.global_position).normalized()
		velocity = velocity.lerp(-direction * max_speed, acceleration * delta)
	else:
		velocity = velocity.lerp(Vector2.ZERO, drag)

func _seeking_healer_state(delta: float) -> void:
	if not current_friendly_target or not is_instance_valid(current_friendly_target):
		current_state = "FOLLOWING_PLAYER"
		current_friendly_target = null
		return
	var distance := global_position.distance_to(current_friendly_target.global_position)
	if distance > 48.0:
		var direction := global_position.direction_to(current_friendly_target.global_position)
		velocity = velocity.lerp(direction * max_speed, acceleration * delta)
	else:
		velocity = Vector2.ZERO

func _find_nearest_healer() -> CharacterBody2D:
	var nearest: CharacterBody2D = null
	var min_dist: float = INF
	for healer in get_tree().get_nodes_in_group("healing_npcs"):
		if is_instance_valid(healer) and healer is CharacterBody2D:
			var dist := global_position.distance_to(healer.global_position)
			if dist < min_dist:
				min_dist = dist
				nearest = healer as CharacterBody2D
	return nearest

# --- Abilities ---
func _perform_song_of_courage() -> void:

func _perform_song_of_courage() -> void:
	# Activate courage aura to buff allies
	_show_casting_text("Song of Courage")
	current_state = "CASTING"
	await get_tree().create_timer(1.0).timeout
	ability_cooldowns["courage"] = song_of_courage_rate
	_activate_courage_aura()
	current_state = "FOLLOWING_PLAYER"

func _perform_song_of_renewal() -> void:
	# Activate renewal aura to heal allies, including self
	_show_casting_text("Song of Renewal")
	current_state = "CASTING"
	await get_tree().create_timer(1.0).timeout
	ability_cooldowns["renewal"] = song_of_renewal_rate
	_activate_renewal_aura()
	if current_health < max_health:
		heal(4) # Match renewal_aura.gd's heal_amount
	current_state = "FOLLOWING_PLAYER"

func _perform_symphony_of_fate(target: CharacterBody2D) -> void:
	# Fire sonic projectile at the closest enemy
	_show_casting_text("Symphony of Fate")
	current_state = "CASTING"
	if target and is_instance_valid(target):
		current_target = target
		_spawn_ability_projectile(target)
	else:
		var new_target = _find_closest_mob()
		if new_target and is_instance_valid(new_target) and _has_clear_line_to_target(new_target):
			current_target = new_target
			_spawn_ability_projectile(new_target)
	ability_cooldowns["symphony"] = symphony_of_fate_rate
	current_state = "FOLLOWING_PLAYER"

func _perform_finale() -> void:
	# Deal instant damage to all enemies within finale_range, boosted by auras
	_show_casting_text("Finale")
	current_state = "CASTING"
	if finale_particles and is_instance_valid(finale_particles):
		finale_particles.emitting = true
	if finale_sound and is_instance_valid(finale_sound):
		finale_sound.play()
	var base_finale_damage: int = 25
	var damage_boost: float = 1.0 + 0.5 * (int(courage_aura.visible) + int(renewal_aura.visible))
	var final_damage: int = int(base_finale_damage * damage_boost)
	var hit_count: int = 0
	for mob in get_tree().get_nodes_in_group("monsters"):
		if is_instance_valid(mob) and mob.visible and mob.has_method("take_damage"):
			var distance = global_position.distance_to(mob.global_position)

func _activate_renewal_aura() -> void:
	# Show renewal aura (effects in aura script)
	renewal_aura.visible = true
	renewal_aura_timer.start()

func _spawn_ability_projectile(target: CharacterBody2D) -> void:
	if not bullet_pool or not muzzle or not target or not is_instance_valid(target):
		return
	var projectile = bullet_pool.spawn()
	if not projectile:
		return
	var direction := muzzle.global_position.direction_to(target.global_position)
	projectile.owner_group = "friendly"
	if projectile.has_method("set_damage"):
		projectile.set_damage(base_damage * damage_modifier)

